// Flat ESLint config for the Amar Dokan POS codebase (added in Phase 1 fix).
// Deliberately lenient on legacy code: `any` and unused vars are warnings,
// not errors, so `npm run lint` stays green on the existing tree while still
// catching real mistakes (undefined vars, unreachable code, etc.).
import js from '@eslint/js';
import tseslint from 'typescript-eslint';
import reactHooks from 'eslint-plugin-react-hooks';
import globals from 'globals';

export default tseslint.config(
  // Phase 2: android/app/src/main/assets/** is generated by `cap sync`
  // (a copy of dist/) — never lint build output.
  { ignores: ['dist/**', 'node_modules/**', 'data/**', 'public/**', 'android/app/src/main/assets/**'] },
  // Phase 2: Node scripts (.mjs tooling) run under Node globals.
  {
    files: ['scripts/**/*.mjs', 'tests/e2e/*.mjs'],
    languageOptions: { globals: globals.node },
  },
  js.configs.recommended,
  ...tseslint.configs.recommended,
  {
    plugins: { 'react-hooks': reactHooks },
    rules: { 'react-hooks/exhaustive-deps': 'warn' },
  },
  {
    rules: {
      '@typescript-eslint/no-explicit-any': 'off',
      '@typescript-eslint/no-unused-vars': 'warn',
      'no-unused-vars': 'off',
      'no-empty': 'warn',
      'no-constant-condition': 'warn',
    },
  },
);
